export const NULL = "-- 1. NULL không bằng gì cả, kể cả NULL\nSELECT count(*) FILTER (WHERE \"giamGia\" = NULL)  AS bang_null,\n       count(*) FILTER (WHERE \"giamGia\" IS NULL) AS is_null,\n       count(*) FILTER (WHERE \"giamGia\" &lt;&gt; 20)    AS khac_20,\n       count(*) FILTER (WHERE \"giamGia\" IS DISTINCT FROM 20) AS distinct_20,\n       count(*) AS tong\nFROM \"DatLich\";\n bang_null | is_null | khac_20 | distinct_20 | tong \n-----------+---------+---------+-------------+------\n         0 |    2400 |     300 |        2700 | 3000\n(1 row)\n\nSELECT NULL = NULL AS a, NULL &lt;&gt; 1 AS b, NOT (NULL = 1) AS c, NULL IS NULL AS d;\n a | b | c | d \n---+---+---+---\n   |   |   | t\n(1 row)";
export const NOT_IN = "-- 2. NOT IN gặp một NULL trong danh sách: không trả dòng nào\nCREATE TEMP TABLE lop_bi_khoa(lop text);\nCREATE TABLE\nINSERT INTO lop_bi_khoa VALUES ('SE181'), (NULL);       -- ai đó nhập một dòng trống\nINSERT 0 2\nSELECT count(*) AS not_in    FROM \"NguoiDung\" n WHERE n.lop NOT IN (SELECT lop FROM lop_bi_khoa);\n not_in \n--------\n      0\n(1 row)\n\nSELECT count(*) AS not_exists FROM \"NguoiDung\" n WHERE NOT EXISTS (SELECT 1 FROM lop_bi_khoa k WHERE k.lop = n.lop);\n not_exists \n------------\n        248\n(1 row)";
export const NULL_SUM = "-- 3. Phép tính gặp NULL: cả biểu thức thành NULL, SUM lặng lẽ bỏ dòng đó\nSELECT sum(p.\"giaGio\" * d.\"soGio\" * (100 - d.\"giamGia\") / 100)                AS doanh_thu_sai,\n       sum(p.\"giaGio\" * d.\"soGio\" * (100 - COALESCE(d.\"giamGia\", 0)) / 100)   AS doanh_thu_dung\nFROM \"DatLich\" d JOIN \"Phong\" p ON p.id = d.\"phongId\" WHERE d.\"trangThai\" = 'DA_DUYET';\n doanh_thu_sai | doanh_thu_dung \n---------------+----------------\n      69600000 |      225600000\n(1 row)";
