export const FANOUT = "-- 4. JOIN nhân dòng: doanh thu theo toà = tiền phòng (ThanhToan) + tiền thiết bị (ThueThietBi)\n--    Bản \"tự nhiên\" viết một mạch JOIN cả hai bảng con:\nSELECT p.toa, sum(t.\"soTien\") AS tien_phong, sum(tb.gia) AS tien_thiet_bi, count(*) AS so_dong\nFROM \"DatLich\" d\nJOIN \"Phong\" p           ON p.id = d.\"phongId\"\nJOIN \"ThanhToan\" t       ON t.\"datLichId\" = d.id\nLEFT JOIN \"ThueThietBi\" tb ON tb.\"datLichId\" = d.id\nWHERE d.\"trangThai\" = 'DA_DUYET'\nGROUP BY p.toa ORDER BY p.toa;\n  toa  | tien_phong | tien_thiet_bi | so_dong \n-------+------------+---------------+---------\n Alpha |   69300000 |      15000000 |    1200\n Beta  |   68600000 |      15000000 |    1200\n Delta |   67200000 |      15000000 |    1200\n Gamma |   67900000 |      15000000 |    1200\n(4 rows)\n\n-- Kiểm: tổng tiền phòng thật sự đã thu là bao nhiêu?\nSELECT sum(\"soTien\") AS tien_phong_that FROM \"ThanhToan\";\n tien_phong_that \n-----------------\n       234000000\n(1 row)\n\n-- Soi một lượt đặt: bao nhiêu dòng sau JOIN?\nSELECT d.id, t.\"soTien\", tb.ten\nFROM \"DatLich\" d JOIN \"ThanhToan\" t ON t.\"datLichId\" = d.id LEFT JOIN \"ThueThietBi\" tb ON tb.\"datLichId\" = d.id\nWHERE d.id = 6;\n id | soTien |    ten     \n----+--------+------------\n  6 |  24000 | Máy chiếu\n  6 |  24000 | Bộ Arduino\n  6 |  56000 | Máy chiếu\n  6 |  56000 | Bộ Arduino\n(4 rows)";
export const FANOUT_SUA = "-- SỬA: gộp từng bảng con về MỘT dòng mỗi lượt đặt TRƯỚC khi JOIN\nWITH tt AS (SELECT \"datLichId\", sum(\"soTien\") AS tien FROM \"ThanhToan\" GROUP BY \"datLichId\"),\n     tb AS (SELECT \"datLichId\", sum(gia) AS tien FROM \"ThueThietBi\" GROUP BY \"datLichId\")\nSELECT p.toa, sum(tt.tien) AS tien_phong, sum(tb.tien) AS tien_thiet_bi, count(*) AS so_luot\nFROM \"DatLich\" d\nJOIN \"Phong\" p ON p.id = d.\"phongId\"\nJOIN tt ON tt.\"datLichId\" = d.id\nLEFT JOIN tb ON tb.\"datLichId\" = d.id\nWHERE d.\"trangThai\" = 'DA_DUYET'\nGROUP BY p.toa ORDER BY p.toa;\n  toa  | tien_phong | tien_thiet_bi | so_luot \n-------+------------+---------------+---------\n Alpha |   59400000 |       7500000 |     450\n Beta  |   58800000 |       7500000 |     450\n Delta |   57600000 |       7500000 |     450\n Gamma |   58200000 |       7500000 |     450\n(4 rows)";
export const LEFT_WHERE = "-- 5. LEFT JOIN bị WHERE biến thành INNER JOIN: \"mọi phòng toà Alpha kèm số lượt ngày 30/11 (UTC)\"\nSELECT count(*) AS so_phong FROM (\n  SELECT p.id, count(d.id) AS so_luot\n  FROM \"Phong\" p LEFT JOIN \"DatLich\" d ON d.\"phongId\" = p.id\n  WHERE p.toa = 'Alpha' AND d.\"batDau\" &gt;= '2026-11-30' AND d.\"batDau\" &lt; '2026-12-01'\n  GROUP BY p.id) x;\n so_phong \n----------\n        2\n(1 row)\n\nSELECT count(*) AS so_phong, count(*) FILTER (WHERE so_luot = 0) AS phong_trong FROM (\n  SELECT p.id, count(d.id) AS so_luot\n  FROM \"Phong\" p LEFT JOIN \"DatLich\" d ON d.\"phongId\" = p.id AND d.\"batDau\" &gt;= '2026-11-30' AND d.\"batDau\" &lt; '2026-12-01'\n  WHERE p.toa = 'Alpha'\n  GROUP BY p.id) x;\n so_phong | phong_trong \n----------+-------------\n       25 |          23\n(1 row)";
export const COUNT_SAO = "-- 6. count(*) với count(cột) sau LEFT JOIN\nSELECT p.ten, count(*) AS count_sao, count(d.id) AS count_id\nFROM \"Phong\" p LEFT JOIN \"DatLich\" d ON d.\"phongId\" = p.id AND d.\"batDau\" &gt;= '2026-11-30'\nWHERE p.id IN (1, 2) GROUP BY p.ten ORDER BY p.ten;\n   ten   | count_sao | count_id \n---------+-----------+----------\n Lab 101 |         1 |        0\n Lab 102 |         1 |        0\n(2 rows)";
export const COLLATE = "-- 7. Collation: sắp xếp tên tiếng Việt\nSELECT datname, datcollate, datlocprovider FROM pg_database WHERE datname = 'labflow';\n datname | datcollate | datlocprovider \n---------+------------+----------------\n labflow | en_US.utf8 | c\n(1 row)\n\nWITH t(ten) AS (VALUES ('Đặng'), ('Ánh'), ('Bùi'), ('Anh'), ('Dương'), ('Zin'), ('ân'), ('Ân'))\nSELECT string_agg(ten, ' &lt; ' ORDER BY ten)                     AS mac_dinh_en_US,\n       string_agg(ten, ' &lt; ' ORDER BY ten COLLATE \"C\")         AS collate_C,\n       string_agg(ten, ' &lt; ' ORDER BY ten COLLATE \"vi-x-icu\")  AS collate_vi_icu\nFROM t \\gx\n-[ RECORD 1 ]--+-----------------------------------------------\nmac_dinh_en_us | ân &lt; Ân &lt; Anh &lt; Ánh &lt; Bùi &lt; Đặng &lt; Dương &lt; Zin\ncollate_c      | Anh &lt; Bùi &lt; Dương &lt; Zin &lt; Ánh &lt; Ân &lt; ân &lt; Đặng\ncollate_vi_icu | Anh &lt; Ánh &lt; ân &lt; Ân &lt; Bùi &lt; Dương &lt; Đặng &lt; Zin\n\n-- Tìm \"anh\" không ra \"Ánh\": so khớp chuỗi dựa trên ký tự, không bỏ dấu\nSELECT count(*) FILTER (WHERE ten ILIKE '%anh%') AS ilike_anh,\n       count(*) FILTER (WHERE ten ILIKE '%ánh%') AS ilike_anh_dau\nFROM \"NguoiDung\";\n ilike_anh | ilike_anh_dau \n-----------+---------------\n         0 |            55\n(1 row)\n\nCREATE EXTENSION IF NOT EXISTS unaccent;\nNOTICE:  extension \"unaccent\" already exists, skipping\nCREATE EXTENSION\nSELECT unaccent('Đặng Ánh Dương') AS bo_dau,\n       count(*) FILTER (WHERE unaccent(ten) ILIKE unaccent('%anh%')) AS unaccent_anh\nFROM \"NguoiDung\" GROUP BY 1;\n     bo_dau     | unaccent_anh \n----------------+--------------\n Dang Anh Duong |           55\n(1 row)";
export const TZ = "-- 8. timestamptz: Prisma lưu DateTime thành timestamp(3) WITHOUT time zone, giá trị là giờ UTC\nSELECT pg_typeof(\"batDau\") AS kieu, \"batDau\" FROM \"DatLich\" WHERE id = 1;\n            kieu             |       batDau        \n-----------------------------+---------------------\n timestamp without time zone | 2026-11-02 00:00:00\n(1 row)\n\n-- \"Ngày 02/11 theo giờ Việt Nam có bao nhiêu lượt?\" — ba cách viết, ba con số\nSELECT count(*) FILTER (WHERE \"batDau\"::date = '2026-11-02')                                         AS cast_date_utc,\n       count(*) FILTER (WHERE (\"batDau\" AT TIME ZONE 'UTC' AT TIME ZONE 'Asia/Ho_Chi_Minh')::date = '2026-11-02') AS doi_sang_gio_vn,\n       count(*) FILTER (WHERE \"batDau\" &gt;= timestamptz '2026-11-02 00:00+07' AT TIME ZONE 'UTC'\n                          AND \"batDau\" &lt;  timestamptz '2026-11-03 00:00+07' AT TIME ZONE 'UTC')         AS khoang_utc_co_index\nFROM \"DatLich\";\n cast_date_utc | doi_sang_gio_vn | khoang_utc_co_index \n---------------+-----------------+---------------------\n           114 |             100 |                 100\n(1 row)\n\n-- Cột timestamptz thật: ::date phụ thuộc TimeZone của PHIÊN (DBeaver, psql, JDBC mỗi nơi một kiểu)\nCREATE TEMP TABLE tz AS SELECT (\"batDau\" AT TIME ZONE 'UTC') AS luc FROM \"DatLich\";\nSELECT 3000\nSET TIME ZONE 'UTC';              SELECT current_setting('TimeZone') AS phien, count(*) FILTER (WHERE luc::date = '2026-11-02') AS ngay_02 FROM tz;\nSET\n phien | ngay_02 \n-------+---------\n UTC   |     114\n(1 row)\n\nSET TIME ZONE 'Asia/Ho_Chi_Minh'; SELECT current_setting('TimeZone') AS phien, count(*) FILTER (WHERE luc::date = '2026-11-02') AS ngay_02 FROM tz;\nSET\n      phien       | ngay_02 \n------------------+---------\n Asia/Ho_Chi_Minh |     100\n(1 row)\n\nSELECT luc FROM tz LIMIT 1;\n          luc           \n------------------------\n 2026-11-02 07:00:00+07\n(1 row)";
export const TIEM = "$ npx tsx thu/tiem.mts\n&gt; ten = \"Ánh Ân\"\n  SQL: SELECT id, email FROM \"NguoiDung\" WHERE ten = 'Ánh Ân'  params=[]\n  $queryRawUnsafe ghép chuỗi: 5 dòng {\"id\":59,\"email\":\"se18059@fpt.edu.vn\"}\n  SQL: SELECT id, email FROM \"NguoiDung\" WHERE ten = $1  params=[\"Ánh Ân\"]\n  $queryRaw tagged template : 5 dòng\n&gt; ten = \"x' OR '1'='1\"\n  SQL: SELECT id, email FROM \"NguoiDung\" WHERE ten = 'x' OR '1'='1'  params=[]\n  $queryRawUnsafe ghép chuỗi: 300 dòng {\"id\":1,\"email\":\"se18001@fpt.edu.vn\"}\n  SQL: SELECT id, email FROM \"NguoiDung\" WHERE ten = $1  params=[\"x' OR '1'='1\"]\n  $queryRaw tagged template : 0 dòng";
