export const HANG_DOI = "## 3. Hàng đợi khoá: một transaction quên commit + một migration ALTER TABLE = mọi SELECT đều treo\nSELECT pid, application_name AS app, state, wait_event_type AS wt, pg_blocking_pids(pid) AS bi_chan_boi, left(query, 50) AS query\nFROM pg_stat_activity WHERE datname = 'labflow' AND backend_type = 'client backend' AND pid &lt;&gt; pg_backend_pid() ORDER BY backend_start;\n pid |   app   |        state        |   wt   | bi_chan_boi |                       query                        \n-----+---------+---------------------+--------+-------------+----------------------------------------------------\n 687 |         | idle                | Client | {}          | UPDATE \"public\".\"DatLich\" SET \"trangThai\" = $1 WHE\n 722 | dbeaver | idle in transaction | Client | {}          | SELECT count(*) FROM \"DatLich\" WHERE \"phongId\" = 1\n 729 | migrate | active              | Lock   | {722}       | ALTER TABLE \"DatLich\" ADD COLUMN \"ghiChu\" text;\n 736 | api     | active              | Lock   | {729}       | SELECT count(*) FROM \"DatLich\";\n(4 rows)\n\nSELECT l.pid, a.application_name AS app, l.mode, l.granted FROM pg_locks l JOIN pg_stat_activity a USING (pid)\nWHERE l.relation = '\"DatLich\"'::regclass ORDER BY l.granted DESC, a.backend_start;\n pid |   app   |        mode         | granted \n-----+---------+---------------------+---------\n 722 | dbeaver | AccessShareLock     | t\n 729 | migrate | AccessExclusiveLock | f\n 736 | api     | AccessShareLock     | f\n(3 rows)\n\n--- phiên migrate:\nALTER TABLE \"DatLich\" ADD COLUMN \"ghiChu\" text;\nALTER TABLE\n--- phiên api:\nSELECT count(*) FROM \"DatLich\";\n count \n-------\n  3000\n(1 row)";
