export const DEADLOCK_PSQL = "## 1. Hai cửa sổ psql: A khoá phòng 1 rồi 2, B khoá phòng 2 rồi 1\n--- cửa sổ A:\nBEGIN;\nBEGIN\nUPDATE \"Phong\" SET \"giaGio\" = \"giaGio\" + 1000 WHERE id = 1;\nUPDATE 1\nUPDATE \"Phong\" SET \"giaGio\" = \"giaGio\" + 1000 WHERE id = 2;\nERROR:  deadlock detected\nDETAIL:  Process 779 waits for ShareLock on transaction 1561; blocked by process 780.\nProcess 780 waits for ShareLock on transaction 1562; blocked by process 779.\nHINT:  See server log for query details.\nCONTEXT:  while updating tuple (0,2) in relation \"Phong\"\nCOMMIT;\nROLLBACK\n--- cửa sổ B:\nBEGIN;\nBEGIN\nUPDATE \"Phong\" SET \"giaGio\" = \"giaGio\" + 1000 WHERE id = 2;\nUPDATE 1\nUPDATE \"Phong\" SET \"giaGio\" = \"giaGio\" + 1000 WHERE id = 1;\nUPDATE 1\nCOMMIT;\nCOMMIT\n--- log PostgreSQL:\n2026-11-23 22:58:48.589 UTC [779] LOG:  process 779 detected deadlock while waiting for ShareLock on transaction 1561 after 1000.043 ms\n2026-11-23 22:58:48.589 UTC [779] DETAIL:  Process holding the lock: 780. Wait queue: .\n2026-11-23 22:58:48.589 UTC [779] CONTEXT:  while updating tuple (0,2) in relation \"Phong\"\n2026-11-23 22:58:48.589 UTC [779] STATEMENT:  UPDATE \"Phong\" SET \"giaGio\" = \"giaGio\" + 1000 WHERE id = 2;\n2026-11-23 22:58:48.590 UTC [779] ERROR:  deadlock detected\n2026-11-23 22:58:48.590 UTC [779] DETAIL:  Process 779 waits for ShareLock on transaction 1561; blocked by process 780.\n    Process 780 waits for ShareLock on transaction 1562; blocked by process 779.\n    Process 779: UPDATE \"Phong\" SET \"giaGio\" = \"giaGio\" + 1000 WHERE id = 2;\n    Process 780: UPDATE \"Phong\" SET \"giaGio\" = \"giaGio\" + 1000 WHERE id = 1;\n2026-11-23 22:58:48.590 UTC [779] HINT:  See server log for query details.\n2026-11-23 22:58:48.590 UTC [779] CONTEXT:  while updating tuple (0,2) in relation \"Phong\"\n2026-11-23 22:58:48.590 UTC [779] STATEMENT:  UPDATE \"Phong\" SET \"giaGio\" = \"giaGio\" + 1000 WHERE id = 2;";
